"""Host-only, lazy P3 tables generated by pristine WRF's REAL4 p3_init.

No JAX arrays are cached: calling the loader during tracing cannot leak a
tracer to a later executable (E206). Load once before lowering, then pass the
needed table as a device operand. Different variants load separate assets.
"""

from functools import lru_cache
from pathlib import Path
from types import MappingProxyType

import numpy as np

_SHAPES = {
    "2mom": {"ice": (5, 4, 50, 14), "rain": (5, 4, 50, 30, 2)},
    "3mom": {"ice": (11, 5, 4, 50, 15), "rain": (11, 5, 4, 50, 30, 2)},
    "ice_ice": {"number": (25, 4, 5, 25, 4, 5), "mass": (25, 4, 5, 25, 4, 5)},
    "warm": {"mu": (150,), "number_speed": (300, 10),
             "mass_speed": (300, 10), "ventilation": (300, 10)},
}


@lru_cache(maxsize=4)
def load_tables(kind: str):
    """Return immutable NumPy REAL4 arrays in the original Fortran axis order."""
    if kind not in _SHAPES:
        raise ValueError(f"Unknown P3 table kind {kind!r}; choose {tuple(_SHAPES)}")
    with np.load(Path(__file__).with_name("data") / f"{kind}.npz", allow_pickle=False) as archive:
        if set(archive.files) != set(_SHAPES[kind]):
            raise ValueError(f"P3 {kind} table inventory mismatch")
        arrays = {name: archive[name] for name in archive.files}
    for name, array in arrays.items():
        if array.shape != _SHAPES[kind][name] or array.dtype != np.float32:
            raise ValueError(f"P3 {kind}/{name} shape or REAL4 dtype mismatch")
        if not np.isfinite(array).all():
            raise ValueError(f"P3 {kind}/{name} contains nonfinite values")
        array.flags.writeable = False
    return MappingProxyType(arrays)
